using System;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;
namespace Groundworks.FuelFire {
public static class FuelControl {
 public static bool Enabled=true,HarmonyActive;public static int SuppressedNativeExplosions,SpillsCreated,Ignitions;public static double LastReleasedKg;
 public static bool Oxygen(Vector3 position,CelestialBody body){return body!=null&&body.atmosphereContainsOxygen&&FlightGlobals.getStaticPressure((Vector3d)position,body)>.01;}

}

public class GroundworksFuelLeak:PartModule {
 [KSPField(isPersistant=true)]public float leakSeverity;
 [KSPField(guiActive=true,guiName="Fluid leak")]public string leakStatus="Sealed";
 [KSPField(guiActive=true,guiName="Fuel remaining")]public string fuelRemaining="";
 void RefreshFuelReadout(){var fuels=reservoir.slots.Where(s=>s.profile.kind==FluidKind.Fuel).ToArray();Fields["fuelRemaining"].guiActive=leakSeverity>0&&fuels.Length>0;fuelRemaining=string.Join("; ",fuels.Select(s=>s.name+" "+s.amount.ToString("F2")+" / "+s.capacity.ToString("F2")+" u").ToArray());}
 public readonly FuelReservoir reservoir=new FuelReservoir();public FuelFX effects;public Vector3 leakPoint,leakDirection=Vector3.forward;public bool Released;public double FlowKgS{get{return reservoir.LastLeakKgS;}}public double BurnKgS{get{return reservoir.LastBurnKgS;}}public bool Burning{get{return reservoir.Burning;}}
 float sparkUntil,nearbyTimer;bool restored;ConfigNode pendingState;
 public override void OnStart(StartState start){base.OnStart(start);Sync();if(pendingState!=null){reservoir.Load(pendingState);pendingState=null;}restored=true;RefreshFuelReadout();Fields["leakStatus"].guiActive=reservoir.slots.Count>0;}
 public void Sync(){if(part==null)return;foreach(PartResource r in part.Resources){var profile=FuelProfiles.Find(r.resourceName);if(profile==null||r.info==null||r.info.density<=0)continue;var slot=reservoir.slots.FirstOrDefault(x=>x.name==r.resourceName);if(slot==null){slot=new FluidSlot{name=r.resourceName,profile=profile};reservoir.slots.Add(slot);}slot.amount=Math.Max(0,r.amount);slot.capacity=Math.Max(0,r.maxAmount);slot.density=r.info.density;}foreach(var slot in reservoir.slots)if(part.Resources[slot.name]==null){slot.amount=0;slot.capacity=0;}}
 public void Puncture(Vector3 point,Vector3 outDirection,float severity,bool spark){Sync();if(reservoir.slots.Count==0)return;Fields["leakStatus"].guiActive=true;leakSeverity=Mathf.Clamp01(Mathf.Max(leakSeverity,severity));leakPoint=part.transform.InverseTransformPoint(point);leakDirection=part.transform.InverseTransformDirection(outDirection.normalized);if(spark)AddSpark();}
 public void AddSpark(){sparkUntil=Time.time+1;}
 bool Hot(){if(part.skinTemperature>Math.Max(350,part.maxTemp*.35))return true;return Time.time<sparkUntil;}
 public void FixedUpdate(){if(!restored||Released||part==null||vessel==null||vessel.packed||TimeWarp.CurrentRate>4||!FuelControl.Enabled||!FuelRuntime.Enabled||leakSeverity<=0)return;Sync();if(reservoir.slots.Count==0)return;double dt=Math.Min(.25,TimeWarp.fixedDeltaTime);Vector3 point=part.transform.TransformPoint(leakPoint);bool air=FuelControl.Oxygen(point,vessel.mainBody);bool was=reservoir.Burning;reservoir.Step(dt,leakSeverity,air,Hot(),false);foreach(var s in reservoir.slots){var resource=part.Resources[s.name];if(resource!=null)resource.amount=Math.Max(0,Math.Min(resource.amount,s.amount));}RefreshFuelReadout();if(!was&&reservoir.Burning)FuelControl.Ignitions++;leakStatus=reservoir.LastLeakKgS>1e-7?(reservoir.Burning?"Burning ":"Leaking ")+reservoir.LastLeakKgS.ToString("F2")+" kg/s":reservoir.CloudKg>1e-5?"Residual vapour":"Empty";
 nearbyTimer+=TimeWarp.fixedDeltaTime;if(nearbyTimer>.25f){nearbyTimer=0;Nearby(point);}if(reservoir.LastLeakKgS>1e-8||reservoir.CloudKg>1e-5){if(effects==null)effects=FuelFX.Create(part.transform,leakPoint,leakDirection);if(effects!=null){bool gas=reservoir.slots.Where(s=>s.amount>0||s.cloud>0).Any(s=>s.profile.gas);effects.Refresh(reservoir,-((Vector3)FlightGlobals.getGeeForceAtPosition((Vector3d)point)).normalized,gas,false);}}else if(effects!=null){effects.Dispose();effects=null;}if(reservoir.LastBurnKgS>0)part.AddThermalFlux(Math.Min(150,reservoir.LastBurnKgS*8));}
 void Nearby(Vector3 point){if(FuelFX.Active.Any(f=>f!=effects&&f.VisibleFlame&&f.root!=null&&(f.root.transform.position-point).sqrMagnitude<9))AddSpark();var seen=new HashSet<Part>();float radius=.8f+FuelReservoir.VisualScale(reservoir.LastBurnKgS)*2;foreach(var c in Physics.OverlapSphere(point,Mathf.Clamp(radius,1.5f,5))){var other=c.GetComponentInParent<Part>();if(c.isTrigger||c.gameObject.layer==16||c.gameObject.layer==20||other==null||other==part||!seen.Add(other))continue;if(other.skinTemperature>Math.Max(350,other.maxTemp*.35)||other.FindModulesImplementing<ModuleEngines>().Any(e=>e.EngineIgnited&&e.currentThrottle>.01f))AddSpark();if(reservoir.Burning)other.AddThermalFlux(Math.Min(100,reservoir.LastBurnKgS*3)/(1+(other.transform.position-point).sqrMagnitude));}}
 public double ReleaseOnDestruction(){if(Released||part==null||!FuelControl.Enabled||!FuelRuntime.Enabled)return 0;Sync();Released=true;var payload=new FuelReservoir{Burning=reservoir.Burning};foreach(var s in reservoir.slots){if(s.amount<=0&&s.cloud<=0)continue;payload.slots.Add(new FluidSlot{name=s.name,profile=s.profile,amount=s.amount,capacity=Math.Max(s.capacity,s.amount),density=s.density,cloud=s.cloud});var r=part.Resources[s.name];if(r!=null)r.amount=0;}double mass=payload.LiquidRemainingKg;FuelControl.LastReleasedKg=mass;if((payload.LiquidRemainingKg>1e-6||payload.CloudKg>1e-6)&&FuelSpill.Active.Count<(FuelRuntime.Quality==0?8:FuelRuntime.Quality==2?32:16)){var go=new GameObject("GW finite fuel spill");go.transform.position=part.transform.TransformPoint(leakSeverity>0?leakPoint:Vector3.zero);var spill=go.AddComponent<FuelSpill>();FuelSpill.Active.Add(spill);spill.state=payload;spill.body=vessel==null?FlightGlobals.currentMainBody:vessel.mainBody;spill.velocity=part.Rigidbody==null?Vector3.zero:part.Rigidbody.velocity;spill.direction=part.transform.TransformDirection(leakDirection);spill.ignition=Hot()||(part.Rigidbody!=null&&part.Rigidbody.velocity.magnitude>Math.Max(3,part.crashTolerance*.7f));spill.expiry=Time.time+(FuelRuntime.Quality==0?20:FuelRuntime.Quality==2?90:60);spill.sources=part.GetComponentsInChildren<Collider>(true);FuelControl.SpillsCreated++;}foreach(var s in reservoir.slots){s.amount=0;s.cloud=0;}if(effects!=null){effects.Dispose();effects=null;}return mass/1000;}
 void OnCollisionEnter(Collision hit){if(!FuelRuntime.Enabled||!FuelControl.Enabled||part==null||vessel==null||vessel.packed||!HighLogic.LoadedSceneIsFlight||hit.contactCount==0)return;var other=hit.collider.GetComponentInParent<Part>();if(other!=null&&other.vessel==vessel)return;var c=hit.GetContact(0);float speed=Mathf.Abs(Vector3.Dot(hit.relativeVelocity,c.normal));float threshold=Mathf.Max(3,part.crashTolerance*.3f);if(speed<threshold)return;Puncture(c.point,-c.normal,Mathf.Clamp01((speed-threshold)/Mathf.Max(1,part.crashTolerance)),speed>threshold*1.8f);}
 public override void OnSave(ConfigNode node){base.OnSave(node);node.AddValue("leakPoint",leakPoint);node.AddValue("leakDirection",leakDirection);reservoir.Save(node.AddNode("FUEL_CLOUD"));}
 public override void OnLoad(ConfigNode node){base.OnLoad(node);if(node.HasValue("leakPoint"))leakPoint=ConfigNode.ParseVector3(node.GetValue("leakPoint"));if(node.HasValue("leakDirection"))leakDirection=ConfigNode.ParseVector3(node.GetValue("leakDirection"));pendingState=node.GetNode("FUEL_CLOUD");if(restored){Sync();reservoir.Load(pendingState);pendingState=null;}}
 public void Update(){if(effects!=null&&(!HighLogic.LoadedSceneIsFlight||vessel==null||vessel.packed||TimeWarp.CurrentRate>4||!FuelControl.Enabled||!FuelRuntime.Enabled)){effects.Dispose();effects=null;}}
 void OnDisable(){if(effects!=null){effects.Dispose();effects=null;}}
 void OnDestroy(){if(effects!=null)effects.Dispose();}
}
public class FuelSpill:MonoBehaviour {
 public static readonly List<FuelSpill> Active=new List<FuelSpill>();float nearby;
 public FuelReservoir state;public CelestialBody body;public Vector3 velocity,direction;public bool ignition;public float expiry;public Collider[] sources;public FuelFX effects;bool pool;Vector3d frame;
 void Start(){frame=Krakensbane.GetFrameVelocity();GameEvents.onFloatingOriginShift.Add(Shift);}
 void Shift(Vector3d d,Vector3d extra){transform.position-=(Vector3)(d+extra);}
 void FixedUpdate(){if(state==null)return;if(!HighLogic.LoadedSceneIsFlight||TimeWarp.CurrentRate>4||Time.time>expiry||!FuelControl.Enabled||!FuelRuntime.Enabled){Destroy(gameObject);return;}float dt=Mathf.Min(.25f,TimeWarp.fixedDeltaTime);Vector3d current=Krakensbane.GetFrameVelocity();velocity-=(Vector3)(current-frame);frame=current;Vector3 gee=(Vector3)FlightGlobals.getGeeForceAtPosition((Vector3d)transform.position,body);if(!pool){velocity+=gee*dt;Vector3 step=velocity*dt;var hits=Physics.RaycastAll(transform.position,step.normalized,step.magnitude+.05f).OrderBy(h=>h.distance);var hit=hits.FirstOrDefault(h=>h.collider!=null&&!h.collider.isTrigger&&h.collider.gameObject.layer!=16&&h.collider.gameObject.layer!=20&&(sources==null||!sources.Contains(h.collider)));if(hit.collider!=null){transform.position=hit.point+hit.normal*.04f;direction=hit.normal;velocity=Vector3.zero;pool=true;}else transform.position+=step;}
 nearby+=dt;if(nearby>.3f){nearby=0;if(FuelFX.Active.Any(f=>f!=effects&&f.root!=null&&f.VisibleFlame&&(f.root.transform.position-transform.position).sqrMagnitude<9))ignition=true;var seen=new HashSet<Part>();foreach(var c in Physics.OverlapSphere(transform.position,2.5f)){var p=c.GetComponentInParent<Part>();if(c.isTrigger||c.gameObject.layer==16||c.gameObject.layer==20||p==null||!seen.Add(p))continue;if(p.skinTemperature>Math.Max(350,p.maxTemp*.35)||p.FindModulesImplementing<ModuleEngines>().Any(e=>e.EngineIgnited&&e.currentThrottle>.01f))ignition=true;if(state.Burning)p.AddThermalFlux(Math.Min(100,state.LastBurnKgS*3)/(1+(p.transform.position-transform.position).sqrMagnitude));}}bool previous=state.Burning;state.Step(dt,1,FuelControl.Oxygen(transform.position,body),ignition,true);ignition=false;if(!previous&&state.Burning)FuelControl.Ignitions++;if(effects==null)effects=FuelFX.Create(transform,Vector3.zero,direction);if(effects!=null)effects.Refresh(state,-gee.normalized,state.slots.Any(s=>s.profile.gas),pool);if(state.LiquidRemainingKg+state.CloudKg<1e-5)Destroy(gameObject);}
 void OnDestroy(){Active.Remove(this);GameEvents.onFloatingOriginShift.Remove(Shift);if(effects!=null)effects.Dispose();}
}
}
